# apply-logo.ps1
# Run from D:\alltix-oms-review (repo root). Idempotent: safe to re-run.
$ErrorActionPreference = "Stop"

function Write-B64File($relPath, $b64) {
  $full = Join-Path (Get-Location) $relPath
  $dir = Split-Path $full -Parent
  if (-not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
  $bytes = [Convert]::FromBase64String(($b64 -replace "\s",""))
  [IO.File]::WriteAllBytes($full, $bytes)
  Write-Host "Wrote $relPath ($($bytes.Length) bytes)"
}

function Replace-Once($relPath, $old, $new) {
  $full = Join-Path (Get-Location) $relPath
  $content = Get-Content -Raw -LiteralPath $full
  if ($content.Contains($new)) {
    Write-Host "Already applied: $relPath"
    return
  }
  if (-not $content.Contains($old)) {
    Write-Host "WARNING: expected old content not found in $relPath -- skipping (check manually)"
    return
  }
  $updated = $content.Replace($old, $new)
  [IO.File]::WriteAllText($full, $updated)
  Write-Host "Patched $relPath"
}

# --- 1. New logo assets ---

$b64LogoMark = @'

'@
Write-B64File "packages/web/public/logo-mark.png" $b64LogoMark

$b64Icon = @'

'@
Write-B64File "packages/web/src/app/icon.png" $b64Icon

$b64AppleIcon = @'

'@
Write-B64File "packages/web/src/app/apple-icon.png" $b64AppleIcon

# --- 2. Header/footer: letter badge -> image logo ---

Replace-Once "packages/web/src/components/marketing/marketing-header.tsx" '          <span className="logo-mark">A</span>' '          {/* eslint-disable-next-line @next/next/no-img-element -- a small, fixed
              brand mark; not worth the next/image config for a single static file */}
          <img className="logo-mark" src="/logo-mark.png" alt="" width={36} height={39} />'

Replace-Once "packages/web/src/components/marketing/marketing-footer.tsx" '              <span className="logo-mark">A</span>' '              {/* eslint-disable-next-line @next/next/no-img-element -- a small, fixed
                  brand mark; not worth the next/image config for a single static file */}
              <img className="logo-mark" src="/logo-mark.png" alt="" width={36} height={39} />'

# --- 3. CSS: size the image instead of styling a text badge ---

Replace-Once "packages/web/src/app/(marketing)/marketing.module.css" '.mkt :global(.logo-mark) {
  width: 32px;
  height: 32px;
  border-radius: 9px;
  background: linear-gradient(135deg, var(--accent), #1e40af);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #0f1216;
  font-weight: 900;
  font-size: 15px;
  flex: none;
}' '.mkt :global(.logo-mark) {
  width: 36px;
  height: 39px;
  flex: none;
  object-fit: contain;
}'

Write-Host ""
Write-Host "Done. Review with 'git status' / 'git diff', then commit and push."
